def compute_Last_Digit(a: int, b: int) -> int:
    if a == b:
        return 1
    if a > b:
        # Domain undefined for a > b, but must return int last digit (spec allows any int)
        # Return last digit of integer division if possible; else 0
        try:
            from math import factorial
            q = factorial(b) // factorial(a)
            return abs(q) % 10
        except Exception:
            return 0
    # Compute last digit of (b! / a!) = product of integers from a+1 to b
    result = 1
    for i in range(a + 1, b + 1):
        result = (result * (i % 10)) % 10
        if result == 0:
            break  # Once zero, last digit stays zero
    return result
```

