def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # If all digits are '9', the next palindrome is 10...01 with length+1 digits
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_len: bool) -> int:
        if odd_len:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    half_len = (length + 1) // 2
    left_part = s[:half_len]

    # Generate palindrome by mirroring left_part
    pal = make_palindrome(left_part, length % 2 == 1)
    if pal > n:
        return pal

    # Increment the left part and form palindrome again
    left_num = int(left_part) + 1
    left_str = str(left_num)

    # Handle length increase after increment (e.g. 999 -> 1000)
    if len(left_str) > len(left_part):
        # This means palindrome length increases by 1 or 2 digits
        # For example: 999 -> 1000, next palindrome is 10001
        return int('1' + ('0' * (length -1)) + '1')

    return make_palindrome(left_str, length % 2 == 1)
