def find_solution(a: int, b: int, n: int):
    from math import gcd
    # Handle the trivial case a=b=0
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        else:
            return "No solution"
    # Handle cases where one coefficient is zero
    if a == 0:
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return "No solution"
    if b == 0:
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return "No solution"
    # Check gcd divides n
    d = gcd(a, b)
    if n % d != 0:
        return "No solution"
    # Reduce equation by gcd
    a1, b1, n1 = a // d, b // d, n // d

    # Extended Euclidean Algorithm to find one solution to a1*x + b1*y = 1
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        else:
            g, x1, y1 = extended_gcd(bb, aa % bb)
            return (g, y1, x1 - (aa // bb) * y1)

    _, x0, y0 = extended_gcd(a1, b1)
    x0 *= n1
    y0 *= n1

    # Now general solution: x = x0 + k*(b1), y = y0 - k*(a1)
    # We want x,y >= 0
    # So find k such that both are non-negative

    # Inequalities:
    # x0 + k*b1 >= 0 => k >= -x0 / b1
    # y0 - k*a1 >= 0 => k <= y0 / a1

    # Because a1, b1 > 0 or <0, handle sign carefully
    # But since gcd divides both, a1 and b1 can be positive or negative

    # For clarity, handle sign of a1 and b1
    # Note: a1 and b1 can't both be zero here (handled above)
    # We'll normalize so b1>0 for consistency
    if b1 < 0:
        b1 = -b1
        a1 = -a1
        x0 = -x0
        y0 = -y0

    # Compute bounds for k
    from math import ceil, floor

    k_min = ceil(-x0 / b1) if b1 != 0 else float('-inf')
    k_max = floor(y0 / a1) if a1 != 0 else float('inf')

    if k_min > k_max:
        return "No solution"

    # Pick k = k_min to get smallest non-negative x
    k = k_min
    x = x0 + k * b1
    y = y0 - k * a1

    if x < 0 or y < 0:
        # Try k_max as last resort
        k = k_max
        x = x0 + k * b1
        y = y0 - k * a1
        if x < 0 or y < 0:
            return "No solution"

    return (x, y)
```

