def get_total_number_of_sequences(n: int, m: int) -> int:
    if n == 1:
        return m
    # dp[i][x]: number of sequences of length i ending with x
    # i in [1..n], x in [1..m]
    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1
    for _ in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # prefix sums for dp to speed up summation
        prefix = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + dp[x]
        for x in range(1, m + 1):
            # next element >= 2 * x
            start = 2 * x
            if start <= m:
                new_dp[x] = prefix[m] - prefix[start - 1]
            else:
                new_dp[x] = 0
        dp = new_dp
    return sum(dp[1:])
```

