def find_Max(nums):
    left, right = 0, len(nums) - 1
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid
    # left is now the index of the minimum element
    # maximum is element before minimum, considering wrap-around
    return nums[left - 1] if left > 0 else nums[-1]
