def lucky_num(n):
    if n == 0:
        return []
    numbers = list(range(1, 2 * n * 10))  # overshoot range to ensure enough numbers remain
    idx = 1
    while idx < len(numbers) and len(numbers) >= idx + 1:
        step = numbers[idx]
        if step > len(numbers):
            break
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n:
            continue
        else:
            # If length is less than n, extend the numbers and continue sieve
            extend_to = numbers[-1] + 2 * n
            numbers.extend(range(numbers[-1] + 1, extend_to))
    return numbers[:n]
```

