def next_smallest_palindrome(n: int) -> int:
    if n <= 0:
        raise ValueError("No smaller palindrome exists for non-positive input")

    s = str(n)
    length = len(s)

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    def mirror_left_to_right(x: str) -> str:
        half = (len(x) + 1) // 2
        if len(x) % 2 == 0:
            return x[:half] + x[:half][::-1]
        else:
            return x[:half] + x[:half - 1][::-1]

    def decrement_str_num(num: str) -> str:
        arr = list(num)
        i = len(arr) - 1
        while i >= 0:
            if arr[i] == '0':
                arr[i] = '9'
                i -= 1
            else:
                arr[i] = str(int(arr[i]) - 1)
                break
        # Remove leading zeros if any
        while len(arr) > 1 and arr[0] == '0':
            arr.pop(0)
        return ''.join(arr)

    def make_palindrome(left_half: str, length: int) -> str:
        if length % 2 == 0:
            return left_half + left_half[::-1]
        else:
            return left_half + left_half[:-1][::-1]

    def all_nines(x: str) -> bool:
        return all(ch == '9' for ch in x)

    # Special case: single digit > 0
    if length == 1:
        return n - 1

    # If n is palindrome, find largest palindrome strictly smaller than n
    if is_palindrome(s):
        # Special case: numbers like 100...001 -> next smaller palindrome is 9..9 with length-1
        if s[0] == '1' and s[-1] == '1' and all(ch == '0' for ch in s[1:-1]):
            return int('9' * (length - 1))

        left_half_len = (length + 1) // 2
        left_half = s[:left_half_len]

        # Decrement left half until the palindrome formed is strictly less than n
        while True:
            left_half = decrement_str_num(left_half)
            # If length reduced after decrement, means left half rolled over e.g. 100 -> 99
            if len(left_half) < left_half_len:
                return int('9' * (length - 1))
            candidate = make_palindrome(left_half, length)
            candidate_int = int(candidate)
            if candidate_int < n:
                return candidate_int

    else:
        # n not palindrome
        left_half_len = (length + 1) // 2
        left_half = s[:left_half_len]

        candidate = make_palindrome(left_half, length)
        candidate_int = int(candidate)

        if candidate_int < n:
            return candidate_int
        else:
            # Decrement left half until palindrome < n
            while True:
                left_half = decrement_str_num(left_half)
                if len(left_half) < left_half_len:
                    return int('9' * (length - 1))
                candidate = make_palindrome(left_half, length)
                candidate_int = int(candidate)
                if candidate_int < n:
                    return candidate_int
