def find_solution(a: int, b: int, n: int):
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        d, s1, t1 = extended_gcd(y, x % y)
        s = t1
        t = s1 - (x // y) * t1
        return d, s, t

    # Handle special cases where a and b are zero
    if a == 0 and b == 0:
        return 'No solution' if n != 0 else (0, 0)

    d, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % d != 0:
        return 'No solution'

    x0 *= n // d
    y0 *= n // d

    # Adjust sign according to original a, b
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    return (x0, y0)
```

