def get_total_number_of_sequences(n: int, m: int) -> int:
    if n <= 0 or m <= 0:
        return 0
    if n == 1:
        return m
    # dp[length][x] = number of sequences of length 'length' ending with element x
    # We only store current and next arrays to save memory
    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1
    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # Precompute suffix sums of dp for indices >= 2*x
        # Because element[i] >= 2 * element[i-1], next element >= 2*x
        suffix_sum = 0
        # We need to quickly get sum of dp[y] for y in [2*x .. m]
        # We'll build suffix sums from right to left
        suffix_dp = [0] * (m + 2)
        for i in range(m, 0, -1):
            suffix_dp[i] = suffix_dp[i + 1] + dp[i]
        for x in range(1, m + 1):
            low = 2 * x
            if low <= m:
                new_dp[x] = suffix_dp[low]
            else:
                new_dp[x] = 0
        dp = new_dp
    return sum(dp[1:]) if dp else 0
```

