def smallest_missing(seq):
    if not seq:
        # Undefined behavior per spec, choose 1 as reasonable default
        return 1
    prev = None
    for x in seq:
        if prev is None:
            # Check missing smaller than the first element
            # smallest missing integer less than seq[0] could be between 1 and seq[0]
            # If seq[0] > 1, then missing is 1
            if x > 1:
                return 1
        else:
            gap = x - prev
            if gap > 1:
                return prev + 1
        prev = x
    # No gaps inside sequence, check missing smaller than minimum
    min_val = seq[0]
    if min_val > 1:
        return 1
    # If min_val <= 1, check if min_val - 1 is missing (it is, since seq is sorted ascending)
    # So smallest missing less than min_val is min_val - 1
    return min_val - 1 if min_val <= 0 else seq[-1] + 1
```

