import collections

def add_string(text, collection):
    t = type(collection)
    if t is list:
        return [text + item for item in collection]
    elif t is tuple:
        return tuple(text + item for item in collection)
    elif t is set:
        return {text + item for item in collection}
    elif t is frozenset:
        return frozenset(text + item for item in collection)
    elif t is collections.deque:
        return collections.deque(text + item for item in collection)
    else:
        # fallback for unknown collection types preserving type if possible
        try:
            return t(text + item for item in collection)
        except Exception:
            # if cannot instantiate with generator, fallback to list
            return list(text + item for item in collection)
