def sum_Of_product(n):
    def comb(n, k):
        if k < 0 or k > n:
            return 0
        k = min(k, n - k)
        c = 1
        for i in range(1, k + 1):
            c = c * (n - i + 1) // i
        return c
    return sum(comb(n, i) * comb(n, i + 1) for i in range(n))
