```python
def dict_depth(d):
    if not isinstance(d, dict):
        return 0
    max_depth = 1
    for v in d.values():
        if isinstance(v, dict):
            depth = 1 + dict_depth(v)
        elif isinstance(v, (list, tuple)):
            depth = 0
            for item in v:
                depth = max(depth, dict_depth(item))
            if depth:
                depth += 1  # only add 1 if nested dict found within list/tuple
        else:
            depth = 0
        if depth > max_depth:
            max_depth = depth
    return max_depth
```

