def smallest_missing(arr, low, high):
    if low > high:
        return 0
    left, right = low, high
    while left <= right:
        mid = (left + right) // 2
        expected = mid - low
        if arr[mid] == expected:
            left = mid + 1
        elif arr[mid] > expected:
            right = mid - 1
        else:
            # Since arr is sorted and distinct non-negative, arr[mid] < expected cannot happen
            # but if it did, treat as missing on left side.
            right = mid - 1
    return left - low
```

