def lucky_num(n):
    if n <= 0:
        return []
    nums = list(range(1, 2 * n * n, 2))  # sufficiently large odd numbers list
    idx = 1
    while idx < len(nums):
        step = nums[idx]
        if step > len(nums):
            break
        del nums[step - 1::step]
        idx += 1
        if len(nums) >= n:
            continue
        else:
            # If not enough numbers, extend nums and continue
            add_limit = nums[-1] + 2 * n * n
            nums.extend(range(nums[-1] + 2, add_limit, 2))
    return nums[:n]
```

