def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)
    # Handle all 9's case: next palindrome is 10..01 with length+1 digits
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def create_palindrome(left: str, middle: str, odd: bool) -> int:
        if odd:
            return int(left + middle + left[::-1])
        else:
            return int(left + left[::-1])

    odd = (length % 2 != 0)
    if odd:
        left = s[:length // 2]
        middle = s[length // 2]
        right = s[length // 2 + 1:]
    else:
        left = s[:length // 2]
        middle = ''
        right = s[length // 2:]

    # Build palindrome by mirroring left and middle
    candidate = create_palindrome(left, middle, odd)
    if candidate > n:
        return candidate

    # Increment the middle part and build palindrome again
    if odd:
        # increment the middle digit along with left
        left_mid_num = int(left + middle)
        left_mid_num += 1
        new_str = str(left_mid_num)
        # if length changed due to carry, adjust accordingly
        if len(new_str) > len(left + middle):
            # length increased, palindrome length increases by 1
            # e.g. 999 -> 1000, palindrome length increases
            return int('1' + ('0' * (length - 1)) + '1')
        new_left = new_str[:-1]
        new_middle = new_str[-1]
        return create_palindrome(new_left, new_middle, True)
    else:
        # even length, increment left and mirror
        left_num = int(left)
        left_num += 1
        new_left = str(left_num)
        if len(new_left) > len(left):
            # length increased due to carry
            return int('1' + ('0' * (length - 1)) + '1')
        return create_palindrome(new_left, '', False)
```

