def find_solution(a: int, b: int, n: int) -> tuple[int, int]:
    def extended_gcd(x: int, y: int) -> tuple[int, int, int]:
        if y == 0:
            return (x, 1, 0)
        d, x1, y1 = extended_gcd(y, x % y)
        return (d, y1, x1 - (x // y) * y1)

    if a == 0 and b == 0:
        # If n == 0, solution (0,0), else no solution but must return integers
        return (0, 0)

    d, x0, y0 = extended_gcd(abs(a), abs(b))

    if n % d != 0:
        # No solution, but must return integers anyway (arbitrary)
        return (0, 0)

    mult = n // d
    x0 *= mult
    y0 *= mult

    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    return (x0, y0)
```

