```python
def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Handle all 9's case: next palindrome is 10..01 with length+1 digits
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def mirror_left_to_right(s: str) -> str:
        l = len(s)
        half = l // 2
        if l % 2 == 0:
            return s[:half] + s[:half][::-1]
        else:
            return s[:half+1] + s[:half][::-1]

    # Step 1: create palindrome by mirroring left half
    pal = mirror_left_to_right(s)
    pal_int = int(pal)
    if pal_int > n:
        return pal_int

    # Step 2: increment the middle part and mirror again
    s_list = list(s)
    mid = (length - 1) // 2
    left_end = mid
    right_start = length // 2

    # Increment the middle (or middle two digits in even length) and propagate carry if needed
    i = left_end
    while i >= 0:
        if s_list[i] != '9':
            s_list[i] = str(int(s_list[i]) + 1)
            break
        else:
            s_list[i] = '0'
            i -= 1
    else:
        # We have a carry beyond the leftmost digit
        s_list.insert(0, '1')
        length += 1
        s_list[-1] = '1'
        # Build palindrome for this new length number which is 1 followed by zeros and ending with 1
        return int('1' + ('0' * (length - 2)) + '1')

    # For even length, mirror left half to right
    # For odd length, mirror left half + middle to right
    if length % 2 == 0:
        for j in range(length // 2):
            s_list[-j-1] = s_list[j]
    else:
        for j in range(length // 2):
            s_list[-j-1] = s_list[j]

    return int(''.join(s_list))
```

