            return (x, 1, 0)
        g, s, t = extended_gcd(y, x % y)
        return (g, t, s - (x // y) * t)

    # Handle all zero coefficients
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)  # Any integers x,y satisfy 0=0, return one solution
        else:
            raise ValueError("No solution")

    # Handle cases where one coefficient is zero
    if a == 0:
        # Equation: b*y = n
        if b == 0:
            # Already handled above, so no solution here
            raise ValueError("No solution")
        if n % b != 0:
            raise ValueError("No solution")
        return (0, n // b)
    if b == 0:
        # Equation: a*x = n
        if n % a != 0:
            raise ValueError("No solution")
        return (n // a, 0)

    g, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % g != 0:
        raise ValueError("No solution")

    x0 *= n // g
    y0 *= n // g

    # Adjust signs according to original signs of a and b
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    return (x0, y0)
