def maximum(arr, k):
    if k == 0:
        return []
    # Find the maximum k elements without using built-in sort
    # Use set to get unique elements for comparison
    unique = []
    seen = set()
    for x in arr:
        if x not in seen:
            unique.append(x)
            seen.add(x)
    # Find the k-th largest element by selection
    def select_kth_largest(nums, k):
        if not nums:
            return None
        pivot = nums[len(nums)//2]
        left = [x for x in nums if x > pivot]
        mid = [x for x in nums if x == pivot]
        right = [x for x in nums if x < pivot]
        if k <= len(left):
            return select_kth_largest(left, k)
        elif k <= len(left) + len(mid):
            return pivot
        else:
            return select_kth_largest(right, k - len(left) - len(mid))
    # If k equals length of arr, just return sorted ascending without built-in sort
    if k == len(arr):
        # Implement insertion sort ascending
        res = arr[:]
        for i in range(1, len(res)):
            key = res[i]
            j = i - 1
            while j >= 0 and res[j] > key:
                res[j+1] = res[j]
                j -= 1
            res[j+1] = key
        return res
    kth_largest = select_kth_largest(arr, k)
    # Collect all elements >= kth_largest (handle duplicates)
    selected = []
    count_needed = k
    # Count how many elements > kth_largest
    greater_count = sum(1 for x in arr if x > kth_largest)
    # Number of kth_largest elements needed
    kth_count = k - greater_count
    # Add all elements > kth_largest
    for x in arr:
        if x > kth_largest:
            selected.append(x)
    # Add kth_largest elements up to kth_count
    for x in arr:
        if x == kth_largest and kth_count > 0:
            selected.append(x)
            kth_count -= 1
    # Sort selected ascending without built-in sort (insertion sort)
    for i in range(1, len(selected)):
        key = selected[i]
        j = i - 1
        while j >= 0 and selected[j] > key:
            selected[j+1] = selected[j]
            j -= 1
        selected[j+1] = key
    return selected
