        current_depth = 0
        for ch in s:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
                if current_depth < 0:
                    raise ValueError("Unbalanced parentheses: too many closing")
            else:
                raise ValueError("Invalid character found in group")
        if current_depth != 0:
            raise ValueError("Unbalanced parentheses: unmatched opening")
        return max_depth

    return [parse_group(g) for g in groups]
