def next_smallest_palindrome(n: int) -> int:
    # Edge case: If n <= 0, the largest palindrome less than n can be n-1
    # For negative numbers or zero, n-1 is smaller and palindrome check holds as str(n-1)==str(n-1)[::-1].
    if n <= 0:
        return n - 1

    s = str(n)
    length = len(s)

    # If n is a single digit > 0, next smallest palindrome is n-1
    if length == 1:
        return n - 1

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    odd = (length % 2 != 0)
    half_len = (length + 1) // 2

    left = s[:half_len]
    palindrome = make_palindrome(left, odd)

    if palindrome < n:
        return palindrome

    # If palindrome >= n, decrement the left part and make palindrome again
    # Convert left to int, subtract 1, then pad with zeros if necessary
    left_int = int(left) - 1
    if left_int == 0 and length > 1:
        # Special case: all zeros in left side after decrement
        # Example: n=1000, left=10 -> left_int=9, but if left_int=0 means we must return 9..9 palindrome with length-1
        return int('9' * (length - 1))

    left_str = str(left_int)
    # Pad with leading zeros if length decreased (e.g. 1000 -> left=10, left_int=9, left_str='9', length decreased by 1)
    if len(left_str) < len(left):
        left_str = left_str.zfill(len(left))

    palindrome = make_palindrome(left_str, odd)
    return palindrome
```

