def find_solution(a: int, b: int, n: int):
    from math import ceil, floor

    # Handle trivial case: a=0 and b=0
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None

    # Handle special cases when one of a or b is zero
    if a == 0:
        if b == 0:
            return None  # already handled above, but safe
        if n % b == 0:
            y = n // b
            if y >= 0:
                return (0, y)
        return None
    if b == 0:
        if n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return None

    # Extended Euclidean algorithm to find one particular solution
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, s, t = extended_gcd(y, x % y)
        return (g, t, s - (x // y) * t)

    g, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % g != 0:
        return None  # no solution

    # Scale the particular solution to n
    x0 *= n // g
    y0 *= n // g

    # Adjust signs according to original a,b
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    # General solution:
    # x = x0 + k*(b/g)
    # y = y0 - k*(a/g)
    k1 = b // g
    k2 = a // g

    # We want x >= 0 and y >= 0:
    # x0 + k * k1 >= 0  => k >= (-x0)/k1 if k1 > 0 else k <= (-x0)/k1
    # y0 - k * k2 >= 0  => k <= y0/k2 if k2 > 0 else k >= y0/k2

    # Compute bounds for k
    # Note k1 and k2 might be positive or negative, handle accordingly
    def div_ceil(a, b):
        # ceil division a/b for integers
        return -((-a)//b) if b != 0 else None

    def div_floor(a, b):
        # floor division a/b for integers
        return a//b if b != 0 else None

    bounds = []

    if k1 > 0:
        low_k = ceil(-x0 / k1)
    elif k1 < 0:
        high_k = floor(-x0 / k1)
    else:
        # k1 == 0 means b==0 which is handled above, but safe fallback:
        if x0 < 0:
            return None
        low_k = None
        high_k = None

    if k2 > 0:
        high_k2 = floor(y0 / k2)
    elif k2 < 0:
        low_k2 = ceil(y0 / k2)
    else:
        # k2 == 0 means a==0 handled above, fallback:
        if y0 < 0:
            return None
        low_k2 = None
        high_k2 = None

    # Combine bounds depending on sign of k1 and k2
    # Initialize k range as infinite
    k_low = -float('inf')
    k_high = float('inf')

    if k1 > 0:
        k_low = max(k_low, ceil(-x0 / k1))
    elif k1 < 0:
        k_high = min(k_high, floor(-x0 / k1))
    else:
        if x0 < 0:
            return None

    if k2 > 0:
        k_high = min(k_high, floor(y0 / k2))
    elif k2 < 0:
        k_low = max(k_low, ceil(y0 / k2))
    else:
        if y0 < 0:
            return None

    # Now try integer k in [k_low, k_high]
    if k_low > k_high:
        return None

    # Choose k such that x,y are nonnegative
    # Any integer k in [k_low, k_high] is valid; try smallest k satisfying conditions
    # Since we want to minimize x or y is not specified, just pick k_low rounded up
    # but k_low may be -inf, so clamp to integer
    if k_low == -float('inf'):
        k_low_int = int(k_high)  # try the upper bound if possible
    else:
        k_low_int = int(ceil(k_low))

    # Try candidates near k_low_int to find valid solution
    # Because k_low and k_high are finite or infinite, try k in range k_low_int to k_high
    # but since k_high can be inf, limit checks

    # Define a helper to check solution validity
    def check_k(k):
        x = x0 + k * k1
        y = y0 - k * k2
        if x >= 0 and y >= 0 and a * x + b * y == n:
            return (x, y)
        return None

    # Try from k_low_int upward until k_high or 1000 steps max to avoid infinite loop
    max_steps = 1000
    start_k = k_low_int
    if start_k < k_low:
        start_k = int(ceil(k_low))
    if k_high == float('inf'):
        end_k = start_k + max_steps
    else:
        end_k = int(floor(k_high))

    for k in range(start_k, end_k + 1):
        sol = check_k(k)
        if sol is not None:
            return sol

    # If no solution found in range, try from k_high downwards if k_high finite
    if k_high != float('inf'):
        for k in range(end_k, start_k - 1, -1):
            sol = check_k(k)
            if sol is not None:
                return sol

    return None
