def get_total_number_of_sequences(n: int, m: int) -> int:
    if n == 1:
        return m if m >= 1 else 0
    if n <= 0 or m <= 0:
        return 0

    # dp[i][x]: number of sequences of length i starting with element x
    # We only need to keep track for current and next step to save memory.
    current = [0] * (m + 1)
    for x in range(1, m + 1):
        current[x] = 1  # sequences of length 1 starting at x is 1

    for length in range(2, n + 1):
        next_dp = [0] * (m + 1)
        # Prefix sums for optimization
        # For each x, next element y >= 2*x and <= m
        # sum over y in [2*x, m] of current[y]
        prefix = [0] * (m + 2)
        for i in range(m, 0, -1):
            prefix[i] = prefix[i + 1] + current[i]

        for x in range(1, m + 1):
            low = 2 * x
            if low <= m:
                next_dp[x] = prefix[low]
            else:
                next_dp[x] = 0

        current = next_dp

    return sum(current[1:]) if n > 0 else 0
```

