def dif_Square(x: int) -> bool:
    if not isinstance(x, int) or x < 0:
        return False
    if x == 0:
        return True
    # x = a^2 - b^2 = (a-b)(a+b)
    # Let m = a-b, n = a+b, then x = m*n, m < n, m,n have same parity
    # Also a = (m+n)/2, b = (n-m)/2 must be integers -> m,n same parity
    # To check if x is difference of squares, find factor pairs (m,n) of x with m<n,
    # check if m and n have same parity.
    from math import isqrt
    for m in range(1, isqrt(x) + 1):
        if x % m == 0:
            n = x // m
            if (m + n) % 2 == 0:
                return True
    return False
