def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Helper to check palindrome
    def is_palindrome(x: int) -> bool:
        sx = str(x)
        return sx == sx[::-1]

    # Special case: single digit >= 2
    if length == 1:
        return n - 1

    # General case:
    # Construct the palindrome by mirroring the left half to right
    # Then if palindrome >= n, decrement the "half" and mirror again
    half_len = (length + 1) // 2
    left_half = s[:half_len]

    def make_palindrome(left: str, odd_len: bool) -> int:
        if odd_len:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    palindrome = make_palindrome(left_half, length % 2 == 1)

    if palindrome >= n:
        # Need to decrement the left half and mirror again
        # Convert left_half to int and decrement
        left_num = int(left_half) - 1
        if left_num == 0:
            # This happens if input is like 1000, next smaller palindrome is 999
            return int('9' * (length - 1))
        left_str = str(left_num)
        # Pad with zeros if needed (important if decrement reduces length)
        left_str = left_str.zfill(len(left_half))
        palindrome = make_palindrome(left_str, length % 2 == 1)
        # If palindrome length is less than original length (due to decrement),
        # means palindrome is less digits, so return the biggest palindrome with length-1 digits
        if len(str(palindrome)) < length:
            return int('9' * (length - 1))

    # If palindrome >= n still (edge cases), fallback to decrement n-1 and find palindrome by brute force
    if palindrome >= n:
        candidate = n - 1
        while candidate > 0:
            if is_palindrome(candidate):
                return candidate
            candidate -= 1
        # theoretically never reach here for positive n >= 2

    return palindrome
```

