def find_solution(a: int, b: int, n: int):
    if a == 0 and b == 0:
        if n == 0:
            return 0, 0  # any integers x,y satisfy 0*x+0*y=0; return (0,0) as simplest
        else:
            raise ValueError("No solution exists when a=0, b=0 and n!=0")
    # Extended Euclidean Algorithm
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        else:
            g, s, t = extended_gcd(y, x % y)
            return (g, t, s - (x // y) * t)
    g, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % g != 0:
        raise ValueError("No integer solutions exist")
    mul = n // g
    x0 *= mul
    y0 *= mul
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0
    return int(x0), int(y0)
