def text_match_two_three(s: str) -> bool:
    n = len(s)
    for i in range(n - 2):
        first = s[i]
        for repeat_len in (2, 3):
            j = i + 1
            if j + repeat_len - 1 >= n:
                continue
            repeated = s[j]
            if all(s[k] == repeated for k in range(j, j + repeat_len)):
                return True
