def reverse_Array_Upto_K(sequence, K):
    prefix_reversed = sequence[:K][::-1]
    suffix = sequence[K:]
    if isinstance(sequence, tuple):
        return tuple(prefix_reversed) + suffix
    else:
        return type(sequence)(prefix_reversed + list(suffix))
