def str_to_tuple(s: str) -> tuple:
    import re
    if not s.strip():
        return ()
    # Split on commas or whitespace sequences
    parts = re.split(r'[,\s]+', s.strip())
    # Filter out empty strings from split (e.g. multiple separators)
    parts = [p for p in parts if p]
    # Convert numeric parts to int where possible, else keep as str
    result = []
    for p in parts:
        try:
            # Convert to int if possible
            val = int(p)
            result.append(val)
        except ValueError:
            result.append(p)
    return tuple(result)
```

