def count_list(coll) -> int:
    recognized = (list, tuple, dict, set, frozenset)
    if not isinstance(coll, recognized):
        return 0
    count = 1
    if isinstance(coll, dict):
        for k, v in coll.items():
            count += count_list(k)
            count += count_list(v)
    else:
        for item in coll:
            count += count_list(item)
    return count
```

