from collections import Counter

def substract_elements(groups):
    result = []
    for group in groups:
        count = Counter(group)
        leftover = []
        used = Counter()
        for x in group:
            if used[x] < count[x] - (count[x] // 2) * 2:
                leftover.append(x)
                used[x] += 1
            else:
                # Skip elements that form pairs
                if used[x] < count[x]:
                    used[x] += 1
        result.append(leftover)
    return result
```

