```python
def capital_words_spaces(s: str) -> str:
    if not s:
        return s
    result = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isupper():
            # Determine if space needed before this capital sequence
            if i == 0:
                # At start, no leading space
                pass
            else:
                # Insert space before first capital of sequence
                result.append(' ')
            # Collect the consecutive capital letters as acronym
            start = i
            while i < n and s[i].isupper():
                i += 1
            # Append the acronym
            result.append(s[start:i])
            # Append any following lowercase letters (part of the same word)
            start_lower = i
            while i < n and s[i].islower():
                i += 1
            if start_lower < i:
                result.append(s[start_lower:i])
        else:
            # Lowercase letter or non-capital: just append
            result.append(c)
            i += 1
    return ''.join(result)
```

```python
def odd_length_sum(arr):
    total = 0
    n = len(arr)
    prefix_sums = [0] * (n + 1)
    for i in range(n):
        prefix_sums[i + 1] = prefix_sums[i] + arr[i]
    for start in range(n):
        for end in range(start, n):
            sub_sum = prefix_sums[end + 1] - prefix_sums[start]
            if sub_sum % 2 == 0:
                total += sub_sum
    return total
```

